1	package numeric
2	
3	import (
4		"encoding/base64"
5		"encoding/json"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11		"sync/atomic"
12		"time"
13		"unicode/utf8"
14	)
15	
16	// rawBase64Prefix 标记 _raw 字段中的值是原始字节的 base64 编码。
17	// ':' 不在 base64 字母表内，普通文本（即使本身像 base64，如 "abcd"）
18	// 不会以该前缀开头；而 _raw 字段由本版本写入，旧归档不含此字段，
19	// 因此标记无歧义。
20	const rawBase64Prefix = "base64:"
21	
22	// unmarshalRaw 恢复 rawIdentity 写出的字段；带 base64 前缀的兜底值解码回
23	// 原始字节，普通 JSON 字符串原样返回。
24	func unmarshalRaw(s string) (string, error) {
25		if strings.HasPrefix(s, rawBase64Prefix) {
26			b, err := base64.StdEncoding.DecodeString(s[len(rawBase64Prefix):])
27			if err != nil {
28				return "", fmt.Errorf("numeric: 标识原始字节解码失败: %w", err)
29			}
30			return string(b), nil
31		}
32		return s, nil
33	}
34	
35	// identityRaw 携带提交人、请求号的完整字节兜底表示。只有当对应字段含
36	// 非法 UTF-8 字节时相应成员才非空；普通文本记录不写这两个字段，
37	// 保持旧格式归档可直接打开。
38	type identityRaw struct {
39		Submitter string `json:"submitter_raw,omitempty"`
40		RequestID string `json:"request_id_raw,omitempty"`
41	}
42	
43	// rawIdentity 在标识含非法 UTF-8 字节时构造完整字节兜底字段；
44	// 两个标识都是合法 UTF-8 时返回 nil，记录与旧格式完全一致。
45	func rawIdentity(submitter, requestID string) *identityRaw {
46		if utf8.ValidString(submitter) && utf8.ValidString(requestID) {
47			return nil
48		}
49		raw := &identityRaw{}
50		if !utf8.ValidString(submitter) {
51			raw.Submitter = rawBase64Prefix + base64.StdEncoding.EncodeToString([]byte(submitter))
52		}
53		if !utf8.ValidString(requestID) {
54			raw.RequestID = rawBase64Prefix + base64.StdEncoding.EncodeToString([]byte(requestID))
55		}
56		return raw
57	}
58	
59	// resolveIdentity 恢复提交人、请求号：_raw 兜底字段存在且非空时以其
60	// 解码出的完整字节为准，否则使用 JSON 字符串字段（旧归档与普通文本）。
61	func resolveIdentity(plainSub, plainReq string, raw *identityRaw) (string, string, error) {
62		var err error
63		sub, req := plainSub, plainReq
64		if raw != nil {
65			if raw.Submitter != "" {
66				if sub, err = unmarshalRaw(raw.Submitter); err != nil {
67					return "", "", err
68				}
69			}
70			if raw.RequestID != "" {
71				if req, err = unmarshalRaw(raw.RequestID); err != nil {
72					return "", "", err
73				}
74			}
75		}
76		return sub, req, nil
77	}
78	
79	// recordVersion 是落盘记录格式的版本标记。
80	const recordVersion = "numeric-job-v1"
81	
82	// storedJob 是作业在内存中的完整状态，所有字段均由 Store.mu 保护。
83	type storedJob struct {
84		id           uint64
85		submitter    string
86		requestID    string
87		seed         int64
88		values       []int64
89		dependencies []uint64 // 有序直接上游作业号；空表示无依赖
90	
91		queuedAt   time.Time
92		startedAt  time.Time
93		finishedAt time.Time
94	
95		status        Status
96		failureReason string
97		blockerID     uint64
98	
99		// 成功后保存的有效输入与归档（与 succeeded 状态同一次原子写入）。
100		effectiveValues []int64
101		archive         *Archive
102	
103		// canceled 仅存于内存：运行中的作业收到取消/关闭请求后置位，
104		// 计算循环据此尽快中止；终态不会依赖它落盘（终态本身会持久化）。
105		canceled atomic.Bool
106	}
107	
108	// jobRecord 是 storedJob 的落盘 JSON 表示。成功状态与归档在同一记录内，
109	// 一次 temp-file + rename 原子写入，因此对外不会出现“成功却没有结果”。
110	type jobRecord struct {
111		Version string `json:"version"`
112	
113		ID        uint64 `json:"id"`
114		Submitter string `json:"submitter"`
115		RequestID string `json:"request_id"`
116		// IdentityRaw 仅在提交人或请求号含非法 UTF-8 字节时出现，按完整字节
117		// 保真恢复标识；合法 UTF-8（含 U+0000）时缺省，记录与旧格式一致。
118		IdentityRaw   *identityRaw `json:"identity_raw,omitempty"`
119		Seed          int64        `json:"seed"`
120		Values        []int64      `json:"values"`
121		HasDependency bool         `json:"has_dependency"`
122		DependencyID  uint64       `json:"dependency_id"`
123		// Dependencies 为有序直接上游作业号；旧格式记录无此字段，
124		// 恢复时由 HasDependency/DependencyID 推导。
125		Dependencies []uint64 `json:"dependencies,omitempty"`
126	
127		QueuedAt   time.Time `json:"queued_at"`
128		StartedAt  time.Time `json:"started_at,omitempty"`
129		FinishedAt time.Time `json:"finished_at,omitempty"`
130	
131		Status        Status `json:"status"`
132		FailureReason string `json:"failure_reason,omitempty"`
133		BlockerID     uint64 `json:"blocker_id,omitempty"`
134	
135		EffectiveValues []int64  `json:"effective_values,omitempty"`
136		Archive         *Archive `json:"archive,omitempty"`
137	}
138	
139	func jobFileName(id uint64) string {
140		return fmt.Sprintf("job-%020d.json", id)
141	}
142	
143	func (s *Store) jobPath(j *storedJob) string {
144		return filepath.Join(s.dir, jobFileName(j.id))
145	}
146	
147	func encodeRecord(j *storedJob) ([]byte, error) {
148		r := jobRecord{
149			Version: recordVersion,
150	
151			ID:            j.id,
152			Submitter:     j.submitter,
153			RequestID:     j.requestID,
154			IdentityRaw:   rawIdentity(j.submitter, j.requestID),
155			Seed:          j.seed,
156			Values:        append([]int64(nil), j.values...),
157			HasDependency: len(j.dependencies) > 0,
158			DependencyID:  depID(j),
159			Dependencies:  append([]uint64(nil), j.dependencies...),
160	
161			QueuedAt:      j.queuedAt,
162			StartedAt:     j.startedAt,
163			FinishedAt:    j.finishedAt,
164			Status:        j.status,
165			FailureReason: j.failureReason,
166			BlockerID:     j.blockerID,
167	
168			EffectiveValues: append([]int64(nil), j.effectiveValues...),
169			Archive:         j.archive,
170		}
171		return json.MarshalIndent(&r, "", "  ")
172	}
173	
174	// depID 返回首个直接上游作业号（无依赖时为 0）。
175	func depID(j *storedJob) uint64 {
176		if len(j.dependencies) == 0 {
177			return 0
178		}
179		return j.dependencies[0]
180	}
181	
182	// persist 在已持锁的情况下原子写一条作业记录。
183	func (s *Store) persist(j *storedJob) error {
184		// 测试用故障注入点（生产代码中 persistFault 恒为 nil）。
185		if s.persistFault != nil {
186			if err := s.persistFault(j); err != nil {
187				return err
188			}
189		}
190		data, err := encodeRecord(j)
191		if err != nil {
192			return err
193		}
194		return writeFileAtomic(s.dir, jobFileName(j.id), data, 0o600)
195	}
196	
197	// writeFileAtomic 将 data 写入 dir/name：同目录临时文件 → fsync → rename
198	// → 目录 fsync，保证记录要么是旧内容要么是新内容，不会出现半条记录。
199	func writeFileAtomic(dir, name string, data []byte, perm os.FileMode) error {
200		tmp, err := os.CreateTemp(dir, ".tmp-"+name+".*")
201		if err != nil {
202			return err
203		}
204		tmpName := tmp.Name()
205		cleanup := true
206		defer func() {
207			if cleanup {
208				_ = os.Remove(tmpName)
209			}
210		}()
211	
212		if _, err := tmp.Write(data); err != nil {
213			_ = tmp.Close()
214			return err
215		}
216		if err := tmp.Sync(); err != nil {
217			_ = tmp.Close()
218			return err
219		}
220		if err := tmp.Close(); err != nil {
221			return err
222		}
223		if err := os.Chmod(tmpName, perm); err != nil {
224			return err
225		}
226		if err := os.Rename(tmpName, filepath.Join(dir, name)); err != nil {
227			return err
228		}
229		cleanup = false
230		syncDir(dir)
231		return nil
232	}
233	
234	// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
235	func syncDir(dir string) {
236		if d, err := os.Open(dir); err == nil {
237			_ = d.Sync()
238			_ = d.Close()
239		}
240	}
241	
242	// loadDir 扫描目录中的全部作业记录并重建内存索引。
243	//
244	// 恢复规则：
245	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
246	//   - 成功记录缺少归档、校验值对不上，依赖列表重复引用同一直接上游作业号，
247	//     实际输入与原始参数或直接依赖数量不对应，或归档数值结果与有效输入按
248	//     计算规则应得的结果不符时，fail-closed 地标记为失败，维持“成功必有
249	//     完整归档”的不变量；
250	//   - 有依赖的成功记录还要求每个直接上游都存在、恢复后仍是带完整归档的
251	//     成功状态，且实际输入的追加部分逐项等于这些上游按保存的依赖顺序
252	//     排列的总和；上游不可用的同样改判为失败，其失败原因指出直接上游、
253	//     BlockerID 沿链条保留最初的根因（与运行中依赖失败同一规则）；
254	//     仅追加输入对不上而上游全部有效的属于本作业自身归档有误，BlockerID
255	//     保持 0。排队记录的依赖列表若重复引用同一作业号，同样在恢复时直接
256	//     判失败（BlockerID 为 0），不再等待或开始计算；仍在排队的其他作业
257	//     在同一趟升序扫描中按既有依赖规则级联失败。
258	func loadDir(dir string) ([]*storedJob, uint64, error) {
259		entries, err := os.ReadDir(dir)
260		if err != nil {
261			return nil, 0, err
262		}
263		var jobs []*storedJob
264		var maxID uint64
265		for _, e := range entries {
266			name := e.Name()
267			if e.IsDir() {
268				continue
269			}
270			// 清理上一进程崩溃时可能残留的原子写临时文件。
271			if strings.HasPrefix(name, ".tmp-") {
272				_ = os.Remove(filepath.Join(dir, name))
273				continue
274			}
275			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
276				continue
277			}
278			path := filepath.Join(dir, name)
279			data, err := os.ReadFile(path)
280			if err != nil {
281				return nil, 0, err
282			}
283			var r jobRecord
284			if err := json.Unmarshal(data, &r); err != nil {
285				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
286			}
287			if r.Version != recordVersion {
288				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
289			}
290			// 提交人、请求号按完整字节恢复：含非法 UTF-8 字节时以
291			// identity_raw 兜底字段为准，普通文本（含 U+0000）与旧归档原样使用。
292			submitter, requestID, err := resolveIdentity(r.Submitter, r.RequestID, r.IdentityRaw)
293			if err != nil {
294				return nil, 0, fmt.Errorf("numeric: 记录 %s 标识损坏: %w", name, err)
295			}
296			// 成功归档内嵌同一份标识，同样按其自身兜底字段恢复，保证顶层记录
297			// 与归档中的参数逐字节一致。
298			if r.Archive != nil {
299				aSub, aReq, aErr := resolveIdentity(r.Archive.Submitter, r.Archive.RequestID, r.Archive.IdentityRaw)
300				if aErr != nil {
301					return nil, 0, fmt.Errorf("numeric: 记录 %s 归档标识损坏: %w", name, aErr)
302				}
303				r.Archive.Submitter = aSub
304				r.Archive.RequestID = aReq
305			}
306			switch r.Status {
307			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
308			default:
309				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
310			}
311			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
312			// 恢复为只含一个作业号的列表（语义与提交时一致）。
313			deps := append([]uint64(nil), r.Dependencies...)
314			if len(deps) == 0 && r.HasDependency {
315				deps = []uint64{r.DependencyID}
316			}
317			j := &storedJob{
318				id:           r.ID,
319				submitter:    submitter,
320				requestID:    requestID,
321				seed:         r.Seed,
322				values:       append([]int64(nil), r.Values...),
323				dependencies: deps,
324	
325				queuedAt:   r.QueuedAt,
326				startedAt:  r.StartedAt,
327				finishedAt: r.FinishedAt,
328	
329				status:        r.Status,
330				failureReason: r.FailureReason,
331				blockerID:     r.BlockerID,
332	
333				effectiveValues: append([]int64(nil), r.EffectiveValues...),
334				archive:         r.Archive,
335			}
336			if j.status == StatusRunning {
337				failRestoredJob(dir, j, "计算被中断：归档上次关闭时作业仍在运行", 0)
338			}
339			if j.status == StatusSucceeded {
340				// 除完整性外，还必须满足三条独立的对应/复算规则：
341				//  0. 依赖列表自身合法——同一直接上游作业号不能出现两次（相邻或隔着
342				//     其他上游都算）。这与提交时 validateDependenciesLocked 的唯一性
343				//     要求一致；旧版本或被改动的记录可能保存了重复引用，此时即使
344				//     追加值、总和、平方和、摘要、日志与校验值全部自洽，也不能当作
345				//     合法成功归档（重复引用会把同一上游总和追加两次）。这属于本作业
346				//     记录自身有误，在任何上游可用性核对之前判定，BlockerID 为 0，
347				//     不把被重复引用的有效上游判成失败。
348				//  1. 实际输入与原始参数、直接依赖数量逐项对应——原始序列非空且
349				//     按原次序完整出现在实际输入开头，总长度恰为原始长度加上直接
350				//     依赖数；摘要、日志、校验值只与“实际输入”绑定，换成另一份
351				//     序列（如 [-3,2] 冒充 [2,-3]）仍能全套自洽，只有按位置比对
352				//     原始参数与依赖数量才能识别。
353				//  2. 归档中的数值结果必须与实际输入按既有计算规则应得的结果一致：
354				//     日志、摘要与校验值都可能与错误数字自洽，只有按保存的实际
355				//     输入复算才能识别。
356				// 任一不符合都按损坏归档处理。第四条规则——追加部分逐项等于各
357				// 直接上游恢复后的总和——需要全部记录恢复完毕才能核对，
358				// 在排序后的第二趟扫描中执行。
359				var invalidReason string
360				if dupID, dup := duplicateDependency(j); dup {
361					invalidReason = duplicateDependencyReason(dupID)
362				} else if !archiveIntact(j) {
363					invalidReason = "归档不完整或校验值不一致，成功结果不可用"
364				} else if !effectiveInputsCorrespond(j) {
365					invalidReason = "实际输入与原始参数或依赖数量不符，成功结果不可用"
366				} else if !archiveResultsValid(j) {
367					invalidReason = "归档数值结果与有效输入按计算规则应得的结果不符，成功结果不可用"
368				}
369				if invalidReason != "" {
370					// 归档自身校验不通过：属于本作业自身失败，不携带阻断根因。
371					failRestoredJob(dir, j, invalidReason, 0)
372				}
373			}
374			jobs = append(jobs, j)
375			if j.id > maxID {
376				maxID = j.id
377			}
378		}
379		// 恢复后的排列必须与关闭前的接受先后一致：作业号在接受时单调分配，
380		// 按作业号升序即提交先后。记录上的提交时间只用于时间范围过滤，
381		// 不参与排序——本机时钟回拨会让后接受的作业带有更早的时间，
382		// 按时间重排会改变已确定的先后关系（也会让上游作业号更大的
383		// 依赖链在单趟级联扫描中漏掉失败传播）。
384		sort.Slice(jobs, func(a, b int) bool {
385			return jobs[a].id < jobs[b].id
386		})
387		// 第二趟：按作业号升序单趟处理依赖失效。直接上游在提交时必须已存在，
388		// 上游作业号必然更小，因此每个作业被处理时其全部直接上游都已是本次恢复
389		// 确定的最终状态——上游被改判失败时携带的根因作业号可直接沿链条继承，
390		// 不会在每经过一个已归档的中间作业时重新起算。
391		//
392		// 两类作业遵守同一项归因规则（与正常运行中的依赖失败一致）：失败原因
393		// 指出当前作业的直接上游，BlockerID 沿链条保留最初使结果不可用的根因；
394		// 只有本作业自身归档有误（上游全部有效、仅保存的追加输入不符）时
395		// BlockerID 才保持 0。
396		//   - 带依赖的成功记录：追加部分与上游恢复后的结果逐项核对；
397		//   - 排队记录：先检查依赖列表自身是否重复引用同一作业号（本作业自身有误，
398		//     BlockerID 为 0），再按保存的依赖顺序选取最靠前的不可用上游（已
399		//     失败/取消，或记录缺失），立即级联失败，不再等待。
400		//
401		// 依赖列表重复属于记录自身问题，先于一切上游可用性判断：即使被重复引用的
402		// 上游仍在排队，重复记录也要立即失败，而等待该重复记录结果的下游则按既有
403		// 规则把它当作失败上游级联，根因就是该重复记录自身。
404		byID := make(map[uint64]*storedJob, len(jobs))
405		for _, j := range jobs {
406			byID[j.id] = j
407		}
408		for _, j := range jobs {
409			if len(j.dependencies) == 0 {
410				continue
411			}
412			switch j.status {
413			case StatusSucceeded:
414				// 第一趟：按保存的依赖顺序找最靠前的不可用上游（记录缺失或恢复后
415				// 未保持带完整归档的成功状态）。
416				directID, dep, unavailable := pickBlockingUpstream(j, byID, restoredArchiveUpstreamBlocked)
417				if unavailable {
418					// 因直接上游结果失效而失败：根因沿该上游已有的阻断信息保留，
419					// 直接上游记录缺失时以缺失的作业号本身作为根因。
420					root := blockerRoot(dep, directID)
421					failRestoredJob(dir, j, blockedFailureReason(restoredArchiveHead(directID), dep, directID, root), root)
422					continue
423				}
424				// 第二趟：直接上游全部存在且有效，只是本作业保存的追加输入与上游
425				// 总和按位置对不上——属于本作业自身归档有误，不把有效上游判成
426				// 失败或归因给它，BlockerID 保持 0。
427				if _, detail, mismatch := firstAppendedMismatch(j, byID); mismatch {
428					failRestoredJob(dir, j, detail, 0)
429				}
430			case StatusQueued:
431				// 排队记录的依赖列表同样不能重复引用同一作业号：这属于本作业记录
432				// 自身有误，在选取不可用上游之前直接判失败——不能开始计算，也不能
433				// 把同一上游总和追加两次后继续。BlockerID 保持 0，不把被重复引用
434				// 且原本有效的上游改成失败。
435				if dupID, dup := duplicateDependency(j); dup {
436					failRestoredJob(dir, j, duplicateDependencyReason(dupID), 0)
437					continue
438				}
439				// 按保存的依赖顺序选取最靠前的不可用上游；其他上游作业号更小
440				// 或失败原因不同都不能改变这个选择。
441				directID, direct, blocked := pickBlockingUpstream(j, byID, restoredQueuedUpstreamBlocked)
442				if !blocked {
443					continue // 上游仍在排队等情况：继续等待，不挡住其他作业。
444				}
445				root := blockerRoot(direct, directID)
446				if direct == nil {
447					// 直接上游的记录在归档目录中缺失，其结果不可能再变为可用：
448					// 以缺失的作业号作为根因，并明确说明结果无法使用。
449					failRestoredJob(dir, j, blockedFailureReason(restoredMissingHead(directID), nil, directID, root), root)
450					continue
451				}
452				failRestoredJob(dir, j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
453			}
454		}
455		return jobs, maxID, nil
456	}
457	
458	// failRestoredJob 收拢重新打开归档时把恢复出的作业改判为失败的统一处理，
459	// 供四类恢复失败共用（调用顺序即各类判定的既有先后）：
460	//   - 上次关闭时仍在运行的作业：计算被中断（第一趟记录扫描）；
461	//   - 原标为成功、但归档完整性、依赖列表唯一性、实际输入对应关系或数值结果
462	//     不符规则的作业：本作业自身归档校验失败（第一趟记录扫描，BlockerID 恒 0）；
463	//   - 排队记录的依赖列表重复引用同一作业号：本作业记录自身有误（第二趟升序
464	//     扫描，BlockerID 恒 0，先于上游可用性判断）；
465	//   - 被不可用直接上游阻断的作业：成功记录复核与排队记录复查（第二趟升序扫描），
466	//     BlockerID 由调用方按 blocker.go 的归因规则给出。
467	//
468	// 处理内容与各处原先内联的步骤完全一致：置失败状态、失败原因与阻断根因；
469	// 已经有完成时间的记录保留该时间，只有没有完成时间的才补上当前时间；
470	// 清除成功归档与实际参与计算的输入，使按作业号读取与按提交人列举都不再返回
471	// 成功归档或实际输入；作业号、提交人、请求号、原始整数次序、种子、依赖次序
472	// 与已有开始时间均不在此改动。归档可正常写入时，变化经同一条记录的一次
473	// 原子替换写回磁盘，而不只停留在内存查询结果中；写入失败维持既有尽力而为
474	// 语义（不因恢复阶段的一次落盘失败让整个归档无法打开）。
475	func failRestoredJob(dir string, j *storedJob, reason string, blocker uint64) {
476		j.status = StatusFailed
477		j.failureReason = reason
478		j.blockerID = blocker
479		if j.finishedAt.IsZero() {
480			j.finishedAt = time.Now().UTC()
481		}
482		j.effectiveValues = nil
483		j.archive = nil
484		if data, err := encodeRecord(j); err == nil {
485			_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
486		}
487	}
488	
489	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
490	func archiveIntact(j *storedJob) bool {
491		a := j.archive
492		if a == nil {
493			return false
494		}
495		// 归档中的原始参数必须与记录顶层字段一致。
496		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
497			a.Seed != j.seed || a.HasDependency != (len(j.dependencies) > 0) {
498			return false
499		}
500		if a.HasDependency && a.DependencyID != depID(j) {
501			return false
502		}
503		// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
504		// 由单依赖字段推导后再比较。
505		aDeps := append([]uint64(nil), a.Dependencies...)
506		if len(aDeps) == 0 && a.HasDependency {
507			aDeps = []uint64{a.DependencyID}
508		}
509		if len(aDeps) != len(j.dependencies) {
510			return false
511		}
512		for i := range j.dependencies {
513			if aDeps[i] != j.dependencies[i] {
514				return false
515			}
516		}
517		if len(a.Values) != len(j.values) {
518			return false
519		}
520		for i := range j.values {
521			if a.Values[i] != j.values[i] {
522				return false
523			}
524		}
525		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
526			return false
527		}
528		for i := range j.effectiveValues {
529			if j.effectiveValues[i] != a.EffectiveValues[i] {
530				return false
531			}
532		}
533		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
534			return false
535		}
536		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
537			return false
538		}
539		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
540			return false
541		}
542		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
543			return false
544		}
545		return true
546	}
547	
548	// archiveResultsValid 按既有计算规则对归档保存的实际输入（effectiveValues，
549	// 已含按顺序追加的上游总和，不再追加）复算总和与平方和，归档中的数值结果
550	// 必须与复算结果完全一致。完整性检查只验证日志、摘要与校验值和所写数字
551	// 自洽，无法识别“数字本身写错但全套字段一致”的记录，因此这里以计算规则
552	// 为准。实际输入按规则会造成 int64 溢出时 ok 为 false，任何数值结果
553	// （包括回绕后的值）都不能作为有效成功结果保留。
554	//
555	// 调用前须已通过 archiveIntact（保证 archive 非空且有效输入非空）。
556	func archiveResultsValid(j *storedJob) bool {
557		a := j.archive
558		sum, sumSquares, _, ok := computeResult(j.effectiveValues, j.seed, nil)
559		if !ok {
560			return false
561		}
562		return a.Sum == sum && a.SumOfSquares == sumSquares
563	}
564	
565	// effectiveInputsCorrespond 校验成功记录中实际参与计算的输入与原始提交
566	// 参数、直接依赖数量之间的对应关系：
567	//   - 原始序列必须非空；
568	//   - 原始序列逐项、按原次序完整出现在实际输入的开头——负数、零与重复
569	//     整数一律按位置判断，不比较总和或平方和，也不忽略次序；
570	//   - 实际输入总长度必须恰好等于原始序列长度加直接依赖数量。无依赖时两份
571	//     序列必须完全相同；有单个或多个依赖时，原始部分之后只能保留每个直接
572	//     上游各占一个位置的追加部分，不能借依赖之名替换、截短原始部分，也不
573	//     能多出未记录的输入。
574	//
575	// 该规则防止把另一份输入的自洽结果挂在原始参数下：例如原始参数为 [2,-3]
576	// 而实际输入被换成 [-3,2] 时，总和与平方和不变，摘要、日志与校验值又只
577	// 绑定实际输入，全套字段仍会自洽，只有按位置比对原始参数并核对追加数量
578	// 才能识别。旧的单依赖记录恢复后依赖列表恰含一个作业号，按同一含义判断。
579	//
580	// 调用前须已通过 archiveIntact（保证 archive 非空、实际输入非空且归档内
581	// 副本与顶层一致）。
582	func effectiveInputsCorrespond(j *storedJob) bool {
583		n := len(j.values)
584		if n == 0 {
585			return false
586		}
587		if len(j.effectiveValues) != n+len(j.dependencies) {
588			return false
589		}
590		for i := 0; i < n; i++ {
591			if j.effectiveValues[i] != j.values[i] {
592				return false
593			}
594		}
595		return true
596	}
597

