257	// 唯一性按作业号判断，而非按上游总和：两个不同上游都得到 3，各引用一次时
258	// 实际输入同样是 [10,3,3]，仍属合法记录，重开后保持成功，次序与结果不变。
259	func TestReopenEqualSumDistinctUpstreamsRemainLegal(t *testing.T) {
260		dir := t.TempDir()
