265		// 作业 3：依赖 [1,2]（作业号不同），追加 [3,3] 合法。
266		down := syntheticSucceededRecord(t, dir, 3,
267			[]int64{10}, []int64{10, 3, 3}, []uint64{1, 2}, base)
