280			t.Fatalf("distinct upstreams with equal sums must stay legal: %s", g.Status)
281		}
282		if g.Archive.Sum != 16 || g.Archive.SumOfSquares != 118 ||
283			g.Archive.Checksum != down.archive.Checksum {
284			t.Fatalf("legal multi-dependency result changed: %+v", g.Archive)
285		}
286		if len(g.Dependencies) != 2 || g.Dependencies[0] != 1 || g.Dependencies[1] != 2 {
287			t.Fatalf("dependency order changed: %v", g.Dependencies)
288		}
289	}
290	
291	// 已经失败或取消的记录即使保存了重复依赖列表，也保留既有终态、原因与根因，
292	// 不被恢复阶段的唯一性检查改写。
293	func TestReopenDuplicateDependencyKeepsExistingTerminalRecords(t *testing.T) {
294		dir := t.TempDir()
295		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
296		syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
297		failedAt := base.Add(2 * time.Second)
298		writeSyntheticRecord(t, dir, &storedJob{
299			id: 2, submitter: "a", requestID: "f",
300			values: []int64{10}, dependencies: []uint64{1, 1},
301			queuedAt: failedAt, finishedAt: failedAt,
302			status:        StatusFailed,
303			failureReason: "既有的失败原因",
304			blockerID:     9,
305		})
306		writeSyntheticRecord(t, dir, &storedJob{
307			id: 3, submitter: "a", requestID: "c",
308			values: []int64{11}, dependencies: []uint64{1, 1},
309			queuedAt: base.Add(3 * time.Second), finishedAt: base.Add(4 * time.Second),
310			status: StatusCanceled,
311		})
312	
313		s, err := Open(dir)
314		if err != nil {
315			t.Fatal(err)
316		}
317		defer s.Close()
318	
319		gf, _ := s.Get(2)
320		if gf.Status != StatusFailed || gf.BlockerID != 9 || gf.FailureReason != "既有的失败原因" {
321			t.Fatalf("existing failed record must be preserved: status=%s blocker=%d reason=%q",
322				gf.Status, gf.BlockerID, gf.FailureReason)
323		}
324		gc, _ := s.Get(3)
325		if gc.Status != StatusCanceled || gc.BlockerID != 0 || gc.FailureReason != "" {
326			t.Fatalf("existing canceled record must be preserved: status=%s blocker=%d reason=%q",
327				gc.Status, gc.BlockerID, gc.FailureReason)
328		}
329	}
