diff --git a/numeric/blocker.go b/numeric/blocker.go
index adf2547..e02a8c0 100644
--- a/numeric/blocker.go
+++ b/numeric/blocker.go
@@ -32,9 +32,16 @@ import "fmt"
 // 该核对只在没有不可用上游时进行，因此“追加输入不符”与“上游不可用”同时出现
 // 时，仍归因给依赖顺序中最靠前的不可用上游。
 //
-// 依赖列表自身重复引用同一作业号（duplicateDependency）同样属于本作业记录自身
